data:
edges = [1 2; 2 3; 3 4; 4 1; 1 5; 4 5; 5 6; 2 6; 3 6];  % 边集合 (每行一条边)
p     = [0 0; 2 0; 2 2; 0 2; 0.5 1; 1.5 1];            % 节点坐标
d     = 2;                                              % 维度 2 或 3

[resultText, isRigid] = RigidOrNot(p, edges, d);
disp(resultText);

figure;
if d == 2
    X = p(:,1); Y = p(:,2);
    scatter(X, Y, 50, 'filled', 'MarkerFaceColor', 'b'); hold on;
    for k = 1:size(edges,1)
        i = edges(k,1); j = edges(k,2);
        plot([X(i), X(j)], [Y(i), Y(j)], 'k-', 'LineWidth', 1.5);
    end
    xlabel('X'); ylabel('Y');
    grid on; axis equal;
elseif d == 3
    X = p(:,1); Y = p(:,2); Z = p(:,3);
    scatter3(X, Y, Z, 50, 'filled'); hold on;
    for k = 1:size(edges,1)
        i = edges(k,1); j = edges(k,2);
        plot3([X(i), X(j)], [Y(i), Y(j)], [Z(i), Z(j)], 'k-', 'LineWidth', 1.5);
    end
    xlabel('X'); ylabel('Y'); zlabel('Z');
    grid on; axis equal;
end


function [a, isRigid] = RigidOrNot(p, edges, d)
    n = size(p,1);
    m = size(edges,1);

    % 构造 incidence matrix H
    H = zeros(m, n);
    for k = 1:m
        i = edges(k,1); j = edges(k,2);
        H(k,i) =  1;
        H(k,j) = -1;
    end

    E = (H * p); % m x d
    g = E ./ vecnorm(E,2,2);

    blocks = cell(m,1);
    for k = 1:m
        gk = g(k,:)';
        ek = E(k,:)';
        P = eye(d) - gk*gk';
        blocks{k} = (P / norm(ek));
    end
    D = blkdiag(blocks{:});

    RB = D * kron(H, eye(d));

    nullDim = size(null(RB),2);
    trivialDim = d + 1;

    if nullDim == trivialDim
        a = '这个图形是刚性的';
        isRigid = true;
    else
        a = '此图不是刚性的';
        isRigid = false;
    end
end
